- `formatCurrency`: zero, negative numbers, string numeric input, non-USD currency
- `formatDate`: Date objects vs strings, timezone boundary dates, invalid date strings
- `cn`: conflicting Tailwind utilities (should merge, not concatenate), falsy values, arrays

```ts
// tests/unit/utils.test.ts
import { cn, formatCurrency, formatDate } from "@/lib/utils";

describe("cn", () => {
  it("merges class names", () => expect(cn("px-2", "px-4")).toBe("px-4"));
  it("drops falsy values", () => expect(cn("a", false && "b", undefined)).toBe("a"));
  it("handles conditional classes", () => expect(cn("a", true && "b")).toBe("a b"));
});

describe("formatCurrency", () => {
  it("formats USD by default", () => expect(formatCurrency(1000)).toBe("$1,000.00"));
  it("accepts string input", () => expect(formatCurrency("500")).toBe("$500.00"));
  it("formats zero", () => expect(formatCurrency(0)).toBe("$0.00"));
  it("formats non-USD currency", () => expect(formatCurrency(100, "EUR")).toContain("100"));
  it("handles negative amounts", () => expect(formatCurrency(-50)).toContain("50"));
});

describe("formatDate", () => {
  it("formats a Date object", () => expect(formatDate(new Date("2025-01-15"))).toMatch(/Jan/));
  it("formats an ISO string", () => expect(formatDate("2025-01-15")).toMatch(/Jan/));
  it("throws or returns Invalid Date for bad input", () => {
    expect(() => formatDate("not-a-date")).not.toThrow(); // define expected behavior
  });
});
