- Each missing credential returns `null`
- Tenant not found → `null`
- User not found for that tenant → `null`
- Correct tenant + wrong password → `null`
- Successful authorization returns full user object with `role`, `tenantId`, `tenantSlug`, `tenantName`
- JWT callback only populates token fields on first sign-in (`user` present)
- Session callback propagates `role`, `tenantId`, `tenantSlug`, `tenantName` from token

```ts
// tests/unit/auth.test.ts
import { authOptions } from "@/lib/auth";
import { prisma } from "@/lib/prisma";
import bcrypt from "bcryptjs";

jest.mock("@/lib/prisma", () => ({ prisma: { tenant: { findUnique: jest.fn() }, user: { findUnique: jest.fn() } } }));

const authorize = (authOptions.providers[0] as any).authorize;

describe("authorize", () => {
  it("returns null when any credential is missing", async () => {
    expect(await authorize({ email: "", password: "x", tenantSlug: "x" })).toBeNull();
    expect(await authorize({ email: "x", password: "", tenantSlug: "x" })).toBeNull();
    expect(await authorize({ email: "x", password: "x", tenantSlug: "" })).toBeNull();
    expect(await authorize(undefined)).toBeNull();
  });

  it("returns null when tenant not found", async () => {
    (prisma.tenant.findUnique as jest.Mock).mockResolvedValue(null);
    expect(await authorize({ email: "a@b.com", password: "pw", tenantSlug: "missing" })).toBeNull();
  });

  it("returns null when user not found", async () => {
    (prisma.tenant.findUnique as jest.Mock).mockResolvedValue({ id: "t1", slug: "acme" });
    (prisma.user.findUnique as jest.Mock).mockResolvedValue(null);
    expect(await authorize({ email: "a@b.com", password: "pw", tenantSlug: "acme" })).toBeNull();
  });

  it("returns null on wrong password", async () => {
    (prisma.tenant.findUnique as jest.Mock).mockResolvedValue({ id: "t1", slug: "acme", name: "Acme" });
    (prisma.user.findUnique as jest.Mock).mockResolvedValue({ id: "u1", email: "a@b.com", hashedPassword: await bcrypt.hash("correct", 10), role: "ADMIN", tenantId: "t1", name: "Alice" });
    expect(await authorize({ email: "a@b.com", password: "wrong", tenantSlug: "acme" })).toBeNull();
  });

  it("returns user object on valid credentials", async () => {
    const hash = await bcrypt.hash("secret", 10);
    (prisma.tenant.findUnique as jest.Mock).mockResolvedValue({ id: "t1", slug: "acme", name: "Acme" });
    (prisma.user.findUnique as jest.Mock).mockResolvedValue({ id: "u1", email: "a@b.com", hashedPassword: hash, role: "HR", tenantId: "t1", name: "Alice" });
    const result = await authorize({ email: "a@b.com", password: "secret", tenantSlug: "acme" });
    expect(result).toMatchObject({ id: "u1", role: "HR", tenantId: "t1", tenantSlug: "acme", tenantName: "Acme" });
  });
});

describe("jwt callback", () => {
  const jwtCb = authOptions.callbacks!.jwt!;
  it("populates token from user on first sign-in", async () => {
    const token = await jwtCb({ token: {}, user: { id: "u1", role: "ADMIN", tenantId: "t1", tenantSlug: "acme", tenantName: "Acme" } as any, trigger: "signIn", session: null, account: null });
    expect(token.role).toBe("ADMIN");
    expect(token.tenantId).toBe("t1");
  });
  it("leaves token unchanged when no user", async () => {
    const token = { role: "HR", tenantId: "t1" };
    const result = await jwtCb({ token, user: undefined as any, trigger: "update", session: null, account: null });
    expect(result.role).toBe("HR");
  });
});
```

