- Employee code zero-padding (`EMP0001`, `EMP0010`, `EMP0100`)
- Default `employmentType = "FULL_TIME"` when omitted
- Duplicate email for same tenant (Prisma unique constraint propagation)
- Tenant isolation: `GET` only returns employees for the authenticated tenant

```ts
// tests/api/employees.test.ts
import { GET, POST } from "@/app/api/employees/route";
import { getServerSession } from "next-auth";
import { prisma } from "@/lib/prisma";

jest.mock("next-auth", () => ({ getServerSession: jest.fn() }));
jest.mock("@/lib/prisma", () => ({ prisma: { employee: { findMany: jest.fn(), count: jest.fn(), create: jest.fn() } } }));

const mockSession = (overrides = {}) => ({ user: { tenantId: "t1", role: "HR", ...overrides } });

describe("GET /api/employees", () => {
  it("returns 401 when not authenticated", async () => {
    (getServerSession as jest.Mock).mockResolvedValue(null);
    const res = await GET();
    expect(res.status).toBe(401);
  });
  it("returns employees for tenant", async () => {
    (getServerSession as jest.Mock).mockResolvedValue(mockSession());
    (prisma.employee.findMany as jest.Mock).mockResolvedValue([{ id: "e1", tenantId: "t1" }]);
    const res = await GET();
    expect(res.status).toBe(200);
    const data = await res.json();
    expect(data).toHaveLength(1);
  });
});

describe("POST /api/employees", () => {
  beforeEach(() => (getServerSession as jest.Mock).mockResolvedValue(mockSession()));

  it("returns 400 when required fields are missing", async () => {
    const req = new Request("http://localhost/api/employees", {
      method: "POST",
      body: JSON.stringify({ firstName: "Alice" }), // missing lastName, email, startDate, baseSalary
    });
    const res = await POST(req as any);
    expect(res.status).toBe(400);
  });

  it("generates padded employee codes", async () => {
    (prisma.employee.count as jest.Mock).mockResolvedValue(9);
    (prisma.employee.create as jest.Mock).mockResolvedValue({ employeeCode: "EMP0010" });
    const req = new Request("http://localhost/api/employees", {
      method: "POST",
      body: JSON.stringify({ firstName: "A", lastName: "B", email: "a@b.com", startDate: "2025-01-01", baseSalary: 50000 }),
    });
    await POST(req as any);
    expect(prisma.employee.create).toHaveBeenCalledWith(
      expect.objectContaining({ data: expect.objectContaining({ employeeCode: "EMP0010" }) })
    );
  });

  it("defaults employmentType to FULL_TIME", async () => {
    (prisma.employee.count as jest.Mock).mockResolvedValue(0);
    (prisma.employee.create as jest.Mock).mockResolvedValue({});
    const req = new Request("http://localhost/api/employees", {
      method: "POST",
      body: JSON.stringify({ firstName: "A", lastName: "B", email: "a@b.com", startDate: "2025-01-01", baseSalary: 50000 }),
    });
    await POST(req as any);
    expect(prisma.employee.create).toHaveBeenCalledWith(
      expect.objectContaining({ data: expect.objectContaining({ employmentType: "FULL_TIME" }) })
    );
  });
});
