- `PUT` with no body fields → should be a no-op update (no data changes)
- `PUT` setting `endDate: null` explicitly
- `DELETE` is a soft-delete (sets `status: TERMINATED`, `endDate: now`) — not a real DB delete
- Cross-tenant access: employee exists but belongs to different tenant → 404

```ts
// tests/api/employees-id.test.ts
import { GET, PUT, DELETE } from "@/app/api/employees/[id]/route";
import { getServerSession } from "next-auth";
import { prisma } from "@/lib/prisma";

jest.mock("next-auth", () => ({ getServerSession: jest.fn() }));
jest.mock("@/lib/prisma", () => ({
  prisma: { employee: { findFirst: jest.fn(), update: jest.fn() } },
}));

const mockCtx = (id: string) => ({ params: Promise.resolve({ id }) });
const mockSession = () => ({ user: { tenantId: "t1" } });

describe("GET /api/employees/[id]", () => {
  it("returns 401 when not authenticated", async () => {
    (getServerSession as jest.Mock).mockResolvedValue(null);
    const res = await GET({} as any, mockCtx("e1") as any);
    expect(res.status).toBe(401);
  });
  it("returns 404 for employee in different tenant", async () => {
    (getServerSession as jest.Mock).mockResolvedValue(mockSession());
    (prisma.employee.findFirst as jest.Mock).mockResolvedValue(null); // not in this tenant
    const res = await GET({} as any, mockCtx("e1") as any);
    expect(res.status).toBe(404);
  });
});

describe("DELETE /api/employees/[id]", () => {
  it("soft-deletes by setting TERMINATED status", async () => {
    (getServerSession as jest.Mock).mockResolvedValue(mockSession());
    (prisma.employee.findFirst as jest.Mock).mockResolvedValue({ id: "e1", tenantId: "t1" });
    (prisma.employee.update as jest.Mock).mockResolvedValue({ id: "e1", status: "TERMINATED" });
    const res = await DELETE({} as any, mockCtx("e1") as any);
    expect(res.status).toBe(200);
    expect(prisma.employee.update).toHaveBeenCalledWith(
      expect.objectContaining({ data: expect.objectContaining({ status: "TERMINATED" }) })
    );
  });
  it("does NOT call prisma.employee.delete", async () => {
    // Verify soft-delete is used — no hard delete
    expect((prisma.employee as any).delete).toBeUndefined();
  });
});
```

