- Upsert behavior: POSTing attendance for same `employeeId+date` updates rather than creates
- `checkIn`/`checkOut` explicitly set to `null` clears the field
- `notes` field is optional

```ts
// tests/api/attendance.test.ts
import { GET, POST } from "@/app/api/attendance/route";
import { getServerSession } from "next-auth";
import { prisma } from "@/lib/prisma";

jest.mock("next-auth", () => ({ getServerSession: jest.fn() }));
jest.mock("@/lib/prisma", () => ({
  prisma: {
    attendance: { findMany: jest.fn(), upsert: jest.fn() },
    employee: { findFirst: jest.fn() },
  },
}));

describe("POST /api/attendance", () => {
  beforeEach(() => (getServerSession as jest.Mock).mockResolvedValue({ user: { tenantId: "t1" } }));

  it("returns 400 when required fields are missing", async () => {
    const req = new Request("http://localhost/api/attendance", {
      method: "POST",
      body: JSON.stringify({ employeeId: "e1" }), // missing date, status
    });
    const res = await POST(req as any);
    expect(res.status).toBe(400);
  });

  it("returns 404 when employee belongs to different tenant", async () => {
    (prisma.employee.findFirst as jest.Mock).mockResolvedValue(null);
    const req = new Request("http://localhost/api/attendance", {
      method: "POST",
      body: JSON.stringify({ employeeId: "e1", date: "2025-01-01", status: "PRESENT" }),
    });
    const res = await POST(req as any);
    expect(res.status).toBe(404);
  });

  it("upserts attendance (update existing record for same date)", async () => {
    (prisma.employee.findFirst as jest.Mock).mockResolvedValue({ id: "e1" });
    (prisma.attendance.upsert as jest.Mock).mockResolvedValue({ id: "a1" });
    const req = new Request("http://localhost/api/attendance", {
      method: "POST",
      body: JSON.stringify({ employeeId: "e1", date: "2025-01-01", status: "LATE" }),
    });
    await POST(req as any);
    expect(prisma.attendance.upsert).toHaveBeenCalledWith(
      expect.objectContaining({ where: { employeeId_date: { employeeId: "e1", date: new Date("2025-01-01") } } })
    );
  });
});
