- `POST` with employee from different tenant → 404
- `POST` with leaveType from different tenant → 404
- `POST` with `days` as a string — `Number(days)` coercion (e.g., `"5"` → `5`, `"abc"` → `NaN`)
- `PATCH` with `status = "PENDING"` → 400 (invalid, only APPROVED/REJECTED/CANCELLED allowed)
- `PATCH` by MANAGER/EMPLOYEE role → 403
- `PATCH` for leave belonging to different tenant → 404
- `PATCH` sets `reviewedAt` to a timestamp

```ts
// tests/api/leaves.test.ts
import { POST } from "@/app/api/leaves/route";
import { PATCH } from "@/app/api/leaves/[id]/route";
import { getServerSession } from "next-auth";
import { prisma } from "@/lib/prisma";

jest.mock("next-auth", () => ({ getServerSession: jest.fn() }));
jest.mock("@/lib/prisma", () => ({
  prisma: {
    leaveRequest: { findMany: jest.fn(), findFirst: jest.fn(), create: jest.fn(), update: jest.fn() },
    employee: { findFirst: jest.fn() },
    leaveType: { findFirst: jest.fn() },
  },
}));

const mockCtx = (id: string) => ({ params: Promise.resolve({ id }) });

describe("POST /api/leaves", () => {
  beforeEach(() => (getServerSession as jest.Mock).mockResolvedValue({ user: { tenantId: "t1" } }));

  it("returns 404 when leave type belongs to different tenant", async () => {
    (prisma.employee.findFirst as jest.Mock).mockResolvedValue({ id: "e1" });
    (prisma.leaveType.findFirst as jest.Mock).mockResolvedValue(null); // not in tenant
    const req = new Request("http://localhost/api/leaves", {
      method: "POST",
      body: JSON.stringify({ employeeId: "e1", leaveTypeId: "lt1", startDate: "2025-01-01", endDate: "2025-01-03", days: 2 }),
    });
    expect((await POST(req as any)).status).toBe(404);
  });
});

describe("PATCH /api/leaves/[id]", () => {
  beforeEach(() => (getServerSession as jest.Mock).mockResolvedValue({ user: { tenantId: "t1", role: "HR" } }));

  it("returns 400 for status=PENDING", async () => {
    const req = new Request("http://localhost/api/leaves/l1", {
      method: "PATCH", body: JSON.stringify({ status: "PENDING" }),
    });
    expect((await PATCH(req as any, mockCtx("l1") as any)).status).toBe(400);
  });

  it("returns 403 for MANAGER role", async () => {
    (getServerSession as jest.Mock).mockResolvedValue({ user: { tenantId: "t1", role: "MANAGER" } });
    const req = new Request("http://localhost/api/leaves/l1", {
      method: "PATCH", body: JSON.stringify({ status: "APPROVED" }),
    });
    expect((await PATCH(req as any, mockCtx("l1") as any)).status).toBe(403);
  });

  it("sets reviewedAt on approval", async () => {
    (prisma.leaveRequest.findFirst as jest.Mock).mockResolvedValue({ id: "l1" });
    (prisma.leaveRequest.update as jest.Mock).mockResolvedValue({ id: "l1", status: "APPROVED", reviewedAt: new Date() });
    const req = new Request("http://localhost/api/leaves/l1", {
      method: "PATCH", body: JSON.stringify({ status: "APPROVED" }),
    });
    await PATCH(req as any, mockCtx("l1") as any);
    expect(prisma.leaveRequest.update).toHaveBeenCalledWith(
      expect.objectContaining({ data: expect.objectContaining({ reviewedAt: expect.any(Date) }) })
    );
  });
});
