- `POST /api/payroll` with duplicate period → 409
- Process: payroll run already `COMPLETED` → 409
- Process: tax = exactly 15% of `baseSalary`, `netSalary` = 85%
- Process: only `ACTIVE` employees are included (INACTIVE and TERMINATED excluded)
- Process: re-processing is idempotent (upsert of payroll items)
- Process: sets `status: "PROCESSING"` before computing, then `"COMPLETED"` after

```ts
// tests/api/payroll.test.ts
import { POST as processPayroll } from "@/app/api/payroll/[id]/process/route";
import { getServerSession } from "next-auth";
import { prisma } from "@/lib/prisma";

jest.mock("next-auth", () => ({ getServerSession: jest.fn() }));
jest.mock("@/lib/prisma", () => ({
  prisma: {
    payrollRun: { findFirst: jest.fn(), findUnique: jest.fn(), update: jest.fn(), create: jest.fn() },
    payrollItem: { upsert: jest.fn() },
    employee: { findMany: jest.fn() },
  },
}));

const mockCtx = (id: string) => ({ params: Promise.resolve({ id }) });

describe("POST /api/payroll/[id]/process", () => {
  beforeEach(() => (getServerSession as jest.Mock).mockResolvedValue({ user: { tenantId: "t1", role: "ADMIN" } }));

  it("returns 409 when payroll is already COMPLETED", async () => {
    (prisma.payrollRun.findFirst as jest.Mock).mockResolvedValue({ id: "pr1", status: "COMPLETED" });
    const req = new Request("http://localhost/api/payroll/pr1/process", { method: "POST" });
    expect((await processPayroll(req as any, mockCtx("pr1") as any)).status).toBe(409);
  });

  it("calculates tax as 15% and net as 85%", async () => {
    (prisma.payrollRun.findFirst as jest.Mock).mockResolvedValue({ id: "pr1", status: "DRAFT" });
    (prisma.payrollRun.update as jest.Mock).mockResolvedValue({});
    (prisma.employee.findMany as jest.Mock).mockResolvedValue([{ id: "e1", baseSalary: "100000" }]);
    (prisma.payrollItem.upsert as jest.Mock).mockResolvedValue({});
    // simulate final update returning completed run
    (prisma.payrollRun.update as jest.Mock)
      .mockResolvedValueOnce({}) // PROCESSING
      .mockResolvedValue({ id: "pr1", status: "COMPLETED", payrollItems: [] });
    const req = new Request("http://localhost/api/payroll/pr1/process", { method: "POST" });
    await processPayroll(req as any, mockCtx("pr1") as any);
    expect(prisma.payrollItem.upsert).toHaveBeenCalledWith(
      expect.objectContaining({
        create: expect.objectContaining({ tax: 15000, netSalary: 85000 }),
      })
    );
  });

  it("excludes INACTIVE and TERMINATED employees", async () => {
    (prisma.payrollRun.findFirst as jest.Mock).mockResolvedValue({ id: "pr1", status: "DRAFT" });
    (prisma.payrollRun.update as jest.Mock).mockResolvedValue({ payrollItems: [] });
    (prisma.employee.findMany as jest.Mock).mockResolvedValue([]);
    const req = new Request("http://localhost/api/payroll/pr1/process", { method: "POST" });
    await processPayroll(req as any, mockCtx("pr1") as any);
    expect(prisma.employee.findMany).toHaveBeenCalledWith(
      expect.objectContaining({ where: expect.objectContaining({ status: "ACTIVE" }) })
    );
  });
});
```

